Implement a range-like iterator with:
    - start, stop, step
    - __iter__ and __next__
    - __len__ and __contains__
    - __reversed__

```python
class CustomRange:
    """
    Implement a range-like iterator with:
    - start, stop, step
    - __iter__ and __next__
    - __len__ and __contains__
    - __reversed__
    """

    def __init__(self, start, stop=None, step=1):
        if stop is None:
            self.start = 0
            self.stop = start
        else:
            self.start = start
            self.stop = stop
        self.step = step
        self.current = self.start

    def __iter__(self):
        self.current = self.start
        return self

    def __next__(self):
        if (self.step > 0 and self.current >= self.stop) or (
            self.step < 0 and self.current <= self.stop
        ):
            raise StopIteration

        result = self.current
        self.current += self.step
        return result

    def __len__(self):
        if self.step > 0:
            return max(0, (self.stop - self.start + self.step - 1) // self.step)
        else:
            return max(0, (self.start - self.stop - self.step - 1) // (-self.step))

    def __contains__(self, value):
        if self.step > 0:
            return (
                self.start <= value < self.stop
                and (value - self.start) % self.step == 0
            )
        else:
            return (
                self.stop < value <= self.start
                and (self.start - value) % (-self.step) == 0
            )

    def __reversed__(self):
        # Create a new CustomRange going backwards
        if self.step > 0:
            new_start = self.stop - 1
            while (new_start - self.start) % self.step != 0:
                new_start -= 1
            return CustomRange(new_start, self.start - 1, -self.step)
        else:
            return CustomRange(self.start, self.stop, -self.step)

    def __repr__(self):
        return f"CustomRange({self.start}, {self.stop}, {self.step})"

# Test
r = CustomRange(0, 10, 2)
print(f"Range: {r}")
print(f"Length: {len(r)}")
print(f"Elements: {list(r)}")
print(f"4 in range: {4 in r}")
print(f"5 in range: {5 in r}")
print(f"Reversed: {list(reversed(r))}")
print()

