Set that maintains insertion order.
    Implements set operations and comparison.

```python
class OrderedSet:
    """
    Set that maintains insertion order.
    Implements set operations and comparison.
    """

    def __init__(self, items=None):
        self._items = {}  # Use dict to maintain order
        if items:
            for item in items:
                self._items[item] = None

    def add(self, item):
        self._items[item] = None

    def remove(self, item):
        del self._items[item]

    def __len__(self):
        return len(self._items)

    def __contains__(self, item):
        return item in self._items

    def __iter__(self):
        return iter(self._items.keys())

    def __repr__(self):
        return f"OrderedSet({list(self._items.keys())})"

    def __eq__(self, other):
        """Equal if same elements in same order"""
        return list(self) == list(other)

    def __le__(self, other):
        """Subset"""
        return all(item in other for item in self)

    def __lt__(self, other):
        """Proper subset"""
        return self <= other and self != other

    def __ge__(self, other):
        """Superset"""
        return all(item in self for item in other)

    def __gt__(self, other):
        """Proper superset"""
        return self >= other and self != other

    def __or__(self, other):
        """Union"""
        result = OrderedSet(self)
        for item in other:
            result.add(item)
        return result

    def __and__(self, other):
        """Intersection"""
        result = OrderedSet()
        for item in self:
            if item in other:
                result.add(item)
        return result

    def __sub__(self, other):
        """Difference"""
        result = OrderedSet()
        for item in self:
            if item not in other:
                result.add(item)
        return result

# Test
s1 = OrderedSet([1, 2, 3, 4])
s2 = OrderedSet([3, 4, 5, 6])
s3 = OrderedSet([1, 2])

print(f"s1 = {s1}")
print(f"s2 = {s2}")
print(f"s3 = {s3}")
print(f"s1 | s2 (union) = {s1 | s2}")
print(f"s1 & s2 (intersection) = {s1 & s2}")
print(f"s1 - s2 (difference) = {s1 - s2}")
print(f"s3 < s1 (subset): {s3 < s1}")
print(f"s1 > s3 (superset): {s1 > s3}")
print()

