Represents a polynomial with arithmetic operations.
    Coefficients stored as [a0, a1, a2, ...] for a0 + a1*x + a2*x^2 + ...

```python
class Polynomial:
    """
    Represents a polynomial with arithmetic operations.
    Coefficients stored as [a0, a1, a2, ...] for a0 + a1*x + a2*x^2 + ...
    """

    def __init__(self, *coefficients):
        self.coefficients = list(coefficients)
        self._remove_trailing_zeros()

    def _remove_trailing_zeros(self):
        """Remove leading zeros from high-degree terms"""
        while len(self.coefficients) > 1 and self.coefficients[-1] == 0:
            self.coefficients.pop()

    def __repr__(self):
        return f"Polynomial{tuple(self.coefficients)}"

    def __str__(self):
        if not self.coefficients:
            return "0"

        terms = []
        for i, coef in enumerate(self.coefficients):
            if coef == 0:
                continue

            if i == 0:
                terms.append(str(coef))
            elif i == 1:
                terms.append(f"{coef}x" if coef != 1 else "x")
            else:
                terms.append(f"{coef}x^{i}" if coef != 1 else f"x^{i}")

        return " + ".join(terms) if terms else "0"

    def __call__(self, x):
        """Evaluate polynomial at x"""
        return sum(coef * (x**i) for i, coef in enumerate(self.coefficients))

    def __add__(self, other):
        """Add two polynomials"""
        max_len = max(len(self.coefficients), len(other.coefficients))
        result = []

        for i in range(max_len):
            c1 = self.coefficients[i] if i < len(self.coefficients) else 0
            c2 = other.coefficients[i] if i < len(other.coefficients) else 0
            result.append(c1 + c2)

        return Polynomial(*result)

    def __sub__(self, other):
        """Subtract polynomials"""
        max_len = max(len(self.coefficients), len(other.coefficients))
        result = []

        for i in range(max_len):
            c1 = self.coefficients[i] if i < len(self.coefficients) else 0
            c2 = other.coefficients[i] if i < len(other.coefficients) else 0
            result.append(c1 - c2)

        return Polynomial(*result)

    def __mul__(self, other):
        """Multiply polynomials"""
        if isinstance(other, (int, float)):
            # Scalar multiplication
            return Polynomial(*[c * other for c in self.coefficients])

        # Polynomial multiplication
        result = [0] * (len(self.coefficients) + len(other.coefficients) - 1)

        for i, c1 in enumerate(self.coefficients):
            for j, c2 in enumerate(other.coefficients):
                result[i + j] += c1 * c2

        return Polynomial(*result)

    def __rmul__(self, scalar):
        return self.__mul__(scalar)

    def __eq__(self, other):
        return self.coefficients == other.coefficients

# Test
p1 = Polynomial(1, 2, 3)  # 1 + 2x + 3x^2
p2 = Polynomial(2, 1)  # 2 + x

print(f"p1 = {p1}")
print(f"p2 = {p2}")
print(f"p1(0) = {p1(0)}")
print(f"p1(1) = {p1(1)}")
print(f"p1(2) = {p1(2)}")
print(f"p1 + p2 = {p1 + p2}")
print(f"p1 - p2 = {p1 - p2}")
print(f"p1 * 2 = {p1 * 2}")
print(f"p1 * p2 = {p1 * p2}")
print()

