Descriptor that computes value once and caches it.

```python
class LazyProperty:
    """
    Descriptor that computes value once and caches it.
    """

    def __init__(self, func):
        self.func = func
        self.name = func.__name__

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self

        # Compute value and cache it
        value = self.func(obj)
        setattr(obj, self.name, value)
        return value

class DataProcessor:
    def __init__(self, data):
        self.data = data

    @LazyProperty
    def sum(self):
        print("Computing sum...")
        return sum(self.data)

    @LazyProperty
    def average(self):
        print("Computing average...")
        return sum(self.data) / len(self.data)

    @LazyProperty
    def max_value(self):
        print("Computing max...")
        return max(self.data)

# Test
dp = DataProcessor([1, 2, 3, 4, 5])
print(f"First access to sum: {dp.sum}")
print(f"Second access to sum: {dp.sum}")  # Cached, no computation
print(f"Average: {dp.average}")
print(f"Max: {dp.max_value}")
print()

