Fixed-size buffer that overwrites oldest elements.
    Supports indexing and slicing.

```python
class CircularBuffer:
    """
    Fixed-size buffer that overwrites oldest elements.
    Supports indexing and slicing.
    """

    def __init__(self, capacity):
        self.capacity = capacity
        self._data = []
        self._start = 0

    def append(self, item):
        if len(self._data) < self.capacity:
            self._data.append(item)
        else:
            self._data[self._start] = item
            self._start = (self._start + 1) % self.capacity

    def __len__(self):
        return len(self._data)

    def __getitem__(self, index):
        if isinstance(index, slice):
            # Handle slicing
            indices = range(*index.indices(len(self)))
            return [self[i] for i in indices]

        # Handle single index
        if index < 0:
            index += len(self)

        if not 0 <= index < len(self):
            raise IndexError("Index out of range")

        actual_index = (self._start + index) % len(self._data)
        return self._data[actual_index]

    def __iter__(self):
        for i in range(len(self)):
            yield self[i]

    def __repr__(self):
        return f"CircularBuffer({list(self)})"

# Test
cb = CircularBuffer(5)
for i in range(8):
    cb.append(i)

print(f"Buffer: {cb}")
print(f"Length: {len(cb)}")
print(f"cb[0]: {cb[0]}")
print(f"cb[-1]: {cb[-1]}")
print(f"cb[1:4]: {cb[1:4]}")
print(f"cb[::2]: {cb[::2]}")
print(f"All elements: {list(cb)}")
